/* Upload -> one editable preview -> one explicit device save. */
(function(){
 'use strict';
 const Engine=window.DegreeRecordImport,Workflow=window.DegreeCourseImportWorkflow,Files=window.DegreeRecordFileReader,$=id=>document.getElementById(id);
 const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 const unitOptions=[['','Not listed'],['semester','Semester credits'],['quarter','Quarter credits'],['competency-unit','Competency units']],statusOptions=[['','Choose progress'],['earned','Finished'],['in-progress','Taking now'],['planned','Not started'],['saved','Considering']];
 let files=[],rows=[],saved=null,baseline='',epoch=0,busy=false,aiStatus=null,finished=false;
 const options=(values,current)=>values.map(([value,label])=>'<option value="'+esc(value)+'"'+(value===(current||'')?' selected':'')+'>'+esc(label)+'</option>').join('');
 const errors=row=>row.issues.some(issue=>issue.severity==='error'),attention=row=>errors(row)||row.match?.kind==='conflict';
 const allRows=()=>files.flatMap(file=>file.rows||[]);
 function reviewFingerprint(file){return JSON.stringify((file.rows||[]).map(row=>({facts:['provider','institution','code','title','credits','creditSystem','status','grade','score','completedOn'].map(key=>row.record?.[key]??null),selected:row.selected!==false})));}
 function rememberPreview(file){file.reviewBaseline=reviewFingerprint(file);}
 function confirmReread(file){
  if(file.reviewBaseline===undefined||file.reviewBaseline===reviewFingerprint(file))return true;
  if(typeof window.confirm!=='function'){showError('Your course edits are kept. This browser could not confirm replacing them. Keep this tab open until you can finish reviewing.');return false;}
  const accepted=window.confirm('Re-read '+file.file.name+'?\n\nYour course edits and selections for this file will be replaced with a fresh reading of the original file. Your saved courses will not change.');
  if(!accepted)announce('Your course edits and selections were kept.');
  return accepted;
 }
 function announce(message){$('import-status').textContent=message;}
 function showError(error){$('import-error').textContent=error instanceof Error?error.message:String(error);$('import-error').hidden=false;}
 function clearError(){$('import-error').hidden=true;$('import-error').textContent='';}
 function step(name){for(const value of['upload','review','done']){const el=$('step-'+value);if(value===name)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');}}
 function setBusy(value){busy=value;$('import-files').disabled=value;$('import-add-files').disabled=value;$('import-cancel').hidden=!value;$('import-apply').disabled=value;}
 function refresh(){saved=Workflow.load(localStorage);const checked=Workflow.inspect(saved.learning,allRows());const map=new Map(checked.map(row=>[row.id,row]));for(const file of files)file.rows=(file.rows||[]).map(row=>map.get(row.id)||row);rows=allRows();}
 function selection(){const selected=rows.filter(row=>row.selected),invalid=selected.some(attention),count=selected.filter(row=>!row.match&&!errors(row)).length,duplicates=selected.filter(row=>row.match?.kind==='duplicate').length;$('import-selection-count').textContent=count+' new course'+(count===1?'':'s')+' selected'+(duplicates?' · '+duplicates+' already saved':'');$('import-apply').disabled=busy||invalid||!selected.length;$('import-apply').textContent=count?'Add '+count+' course'+(count===1?'':'s')+' →':duplicates?'Keep my saved courses →':'Add selected courses →';}
 function rowNotes(row){let html='';if(row.match?.kind==='duplicate')html='<p class="import-row-badge import-badge-duplicate">Already saved · will be skipped</p>';else if(row.match?.kind==='conflict'){const target=row.match.existingIds?.[0];html='<p class="import-row-badge import-badge-conflict">Different version already saved</p><p>Uncheck this row to keep your saved version.'+(target?' <a href="courses.html?tab=mine&amp;record='+encodeURIComponent(target)+'" target="_blank" rel="noopener">Review saved course ↗</a>':'')+'</p>';}else if(!errors(row))html='<p class="import-row-badge import-badge-ready">Ready to add</p>';const problems=row.issues.filter(issue=>issue.severity==='error');html+=problems.map(issue=>'<p class="row-error">'+esc(issue.message)+'</p>').join('');const warnings=row.issues.filter(issue=>issue.severity!=='error');if(warnings.length)html+='<details><summary>'+warnings.length+' detail'+(warnings.length===1?'':'s')+' to review</summary>'+warnings.map(issue=>'<p>'+esc(issue.message)+'</p>').join('')+'</details>';const source=row.source||{},file=files.find(item=>item.id===row.fileId);html+='<details><summary>'+esc(file?.file.name||'Original row')+(source.page?' · page '+source.page:source.row?' · row '+source.row:'')+'</summary>'+(source.term?'<p>'+esc(source.term)+'</p>':'')+'<div class="import-source">'+esc(source.rawLine||JSON.stringify(source.rawValues||{}))+'</div></details>';return html;}
 function field(row,name,type='text',max){return'<input data-row="'+row.id+'" data-field="'+name+'" type="'+type+'" value="'+esc(row.record[name])+'" aria-label="'+esc(name+' for '+(row.record.title||'course'))+'"'+(max?' maxlength="'+max+'"':'')+(type==='number'?' step="any" min="0"':'')+'>';}
 function renderRows(){const visible=rows.filter(row=>!$('import-attention-only').checked||attention(row));$('import-rows').innerHTML=visible.map(row=>'<tr data-course-row="'+row.id+'" class="'+(attention(row)?'has-errors':row.match?'is-duplicate':'')+'"><td><input type="checkbox" data-select="'+row.id+'" aria-label="Add '+esc(row.record.title||'course')+'"'+(row.selected?' checked':'')+'></td><td>'+field(row,'provider','text',120)+(row.record.institution?'<span class="import-small">'+esc(row.record.institution)+'</span>':'')+'</td><td>'+field(row,'code','text',100)+'</td><td>'+field(row,'title','text',160)+'</td><td>'+field(row,'credits','number')+'</td><td><select data-row="'+row.id+'" data-field="creditSystem" aria-label="Credit units for '+esc(row.record.title)+'">'+options(unitOptions,row.record.creditSystem)+'</select></td><td><select data-row="'+row.id+'" data-field="status" aria-label="Progress for '+esc(row.record.title)+'">'+options(statusOptions,row.record.status)+'</select></td><td>'+field(row,'grade','text',10)+'</td><td>'+field(row,'score','number')+'</td><td>'+field(row,'completedOn','date')+'</td><td class="import-row-notes">'+rowNotes(row)+'</td></tr>').join('')||'<tr><td colspan="11">'+(rows.length?'No courses need attention. Uncheck the filter to see all rows.':'No course rows have been read yet.')+'</td></tr>';const problemCount=rows.filter(attention).length;$('import-review-count').textContent=rows.length+' course'+(rows.length===1?'':'s')+' from '+files.filter(file=>file.rows?.length).length+' file'+(files.filter(file=>file.rows?.length).length===1?'':'s')+(problemCount?' · '+problemCount+' need attention':'');$('import-skip-conflicts').hidden=!rows.some(row=>row.match?.kind==='conflict');selection();}
 function renderFiles(){$('import-file-list').innerHTML=files.map(file=>{const result=file.result,canAI=result?.format==='pdf'&&(result.needsAI||file.parsed?.partialReading||!file.rows?.length),kinds=[['unknown','Detect automatically'],['completed-transcript','Transcript / completed courses'],['degree-audit','Degree audit / proposed plan']];let html='<article class="import-file"><div class="import-file-top"><div><p class="import-file-name">'+esc(file.file.name)+'</p><p class="import-file-message">'+esc(file.message||'Waiting to read…')+'</p></div><button type="button" class="import-text-button" data-remove-file="'+file.id+'"'+(busy?' disabled':'')+'>Remove</button></div>';if(result){html+='<div class="import-file-options"><label>Document type<select data-kind-file="'+file.id+'"'+(busy?' disabled':'')+'>'+options(kinds,file.kind)+'</select></label>';if(result.sheets?.length>1)html+='<label>Course sheet<select data-sheet-file="'+file.id+'"'+(busy?' disabled':'')+'>'+options(result.sheets.map(sheet=>[String(sheet.index),sheet.name+(sheet.useful?'':' (no course table)')]),String(result.selectedSheet?.index))+'</select></label>';html+='</div>';if(result.cellIssues?.length)html+='<p class="import-small">'+esc(result.cellIssues.length+' spreadsheet cells need review. Formulas and cached results were not imported.')+'</p>';const issues=[...(file.parsed?.issues||[]).map(issue=>issue.message),...(file.aiIssues||[])];if(issues.length)html+='<details class="import-small"><summary>File reading details</summary>'+issues.map(issue=>'<p>'+esc(issue)+'</p>').join('')+'</details>';if(canAI)html+='<div class="import-ai"><p><strong>'+(result.needsAI?'This PDF includes scanned pages.':'This layout needs another reading method.')+'</strong> Optional AI reading can turn the pages into a course table. You will review the result before saving.</p><label><input type="checkbox" data-ai-consent="'+file.id+'"'+(file.consent?' checked':'')+(busy?' disabled':'')+'>I agree to send this PDF’s page images to Anthropic (Claude) for reading. I can remove identity details from my copy first.</label><button type="button" class="import-secondary" data-read-ai="'+file.id+'"'+(busy||!file.consent?' disabled':'')+'>Read this PDF with AI</button><a class="import-text-link" href="account.html" target="_blank" rel="noopener">Sign in for AI reading ↗</a><p class="import-small">Up to 25 pages. DegreeSteps does not store the document. <a href="privacy/" target="_blank" rel="noopener">Privacy details ↗</a></p></div>';}return html+'</article>';}).join('');$('import-files-panel').hidden=!files.length;}
 function render(){refresh();renderFiles();renderRows();$('import-start').hidden=rows.length>0||finished;$('import-review').hidden=!rows.length||finished;if(rows.length&&!finished)step('review');else if(!finished)step('upload');}
 function parseFile(file,result){const opts={sourceName:file.file.name,documentKind:file.kind||'unknown',sheetName:result.selectedSheet?.name};let parsed;if(file.aiResult)parsed=Engine.fromRecords(file.aiResult.rows,{...opts,documentKind:file.kind==='unknown'?file.aiResult.documentKind:file.kind,extraction:'ai'});else if(result.rows)parsed=Engine.fromRows(result.rows,opts);else if(result.format==='pdf')parsed=Engine.parseTranscript(result.pages,opts);else if(result.format==='text'&&!/[,\t]/.test(result.text.split('\n')[0]))parsed=Engine.parseTranscript([{page:1,text:result.text}],opts);else parsed=Engine.parseCSV(result.text,opts);if(allRows().filter(row=>row.fileId!==file.id).length+parsed.rows.length>500)throw Error('Review up to 500 courses at a time. Remove a file or use a smaller course sheet.');file.parsed=parsed;file.rows=parsed.rows.map((row,index)=>({...row,id:file.id+'-row-'+index,fileId:file.id}));rememberPreview(file);file.message=parsed.rows.length+' course row'+(parsed.rows.length===1?'':'s')+' found'+(result.selectedSheet?' in '+result.selectedSheet.name:'')+(result.needsAI?' · scanned pages still need reading':'')+'.';}
 async function read(file,sheet){file.rows=[];rememberPreview(file);file.parsed=null;file.aiResult=null;file.aiIssues=[];file.message='Reading on this device…';render();const ticket=epoch;try{const result=await file.reader.read(file.file,{sheet,onProgress:progress=>{if(ticket!==epoch)return;file.message=progress.totalPages?'Reading page '+progress.page+' of '+progress.totalPages+' on this device…':'Opening the course sheet on this device…';renderFiles();}});if(ticket!==epoch)return;file.result=result;parseFile(file,result);render();}catch(error){if(ticket!==epoch)return;file.message=error.name==='AbortError'?'Reading cancelled. Choose the file again when you are ready.':error.message;render();}}
 async function chooseFiles(incoming){clearError();if(busy)return;const additions=[...incoming];if(files.length+additions.length>10){showError('Choose up to 10 files per review. Add more after saving these courses.');return;}if(!additions.length)return;const ticket=epoch;finished=false;$('import-success').hidden=true;setBusy(true);try{for(const item of additions){const file={id:'file-'+(++chooseFiles.sequence),file:item,reader:Files.create(),kind:'unknown',rows:[],consent:false};files.push(file);await read(file);if(ticket!==epoch)break;}if(ticket===epoch)render();}catch(error){if(ticket===epoch)showError(error);}finally{if(ticket===epoch){setBusy(false);renderFiles();selection();$('import-files').value='';}}}
 chooseFiles.sequence=0;
 async function status(signal){const response=await fetch('/api/portal/transcript-import',{credentials:'same-origin',cache:'no-store',signal});const body=await response.json();if(!response.ok)throw Error(body.error||'AI reading is temporarily unavailable.');aiStatus=body;return body;}
 async function streamResult(response,onProgress){if(!response.ok||!(response.headers.get('Content-Type')||'').includes('text/event-stream')){const data=await response.json();if(!response.ok)throw Error(data.error||'The scan could not be read.');return data;}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',total=0,result=null;while(true){const part=await reader.read();if(part.done)break;total+=part.value.byteLength;if(total>2*1024*1024){await reader.cancel();throw Error('The scan result exceeded the reading limit. Use fewer pages.');}buffer+=decoder.decode(part.value,{stream:true}).replace(/\r\n/g,'\n');let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);let event='',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim();}if(!data)continue;const value=JSON.parse(data);if(event==='error')throw Error(value.error||'AI reading could not finish. Your saved courses are unchanged.');if(event==='result')result=value;else if(['progress','accepted'].includes(event))onProgress(value);}}if(!result)throw Error('The scan connection ended before a course table arrived. Your saved courses are unchanged. Try a smaller PDF or the spreadsheet template.');return result;}
 async function readAI(file){clearError();if(busy||!file.consent)return;if(file.kind==='unknown'){showError('Choose Transcript / completed courses or Degree audit / proposed plan in the document type above, then read this PDF with AI.');return;}const ticket=epoch;if(!confirmReread(file)||ticket!==epoch||busy||!files.includes(file))return;const controller=new AbortController();file.controller=controller;setBusy(true);renderFiles();let availability;const statusTimeout=setTimeout(()=>controller.abort(),15000);try{availability=await status(controller.signal);if(ticket!==epoch)return;if(availability.requiresSignIn)throw Error('Sign in using the link under this file, then return here and choose Read this PDF with AI. Your file stays open in this tab.');if(!availability.configured)throw Error('AI scan reading is not connected yet. Upload a text-readable transcript or use the spreadsheet template.');}catch(error){if(ticket!==epoch)return;showError(error.name==='AbortError'?'The scan service took too long to respond. Try again, or upload a spreadsheet.':error);setBusy(false);renderFiles();selection();return;}finally{clearTimeout(statusTimeout);}if(ticket!==epoch)return;let timeout;try{file.message='Preparing page images on this device…';renderFiles();const images=await file.reader.renderForAI(file.file,{signal:controller.signal,maxPages:availability.limits?.maxPages||25,onProgress:progress=>{if(ticket!==epoch)return;file.message='Preparing page '+progress.page+' of '+progress.totalPages+'…';renderFiles();}});if(ticket!==epoch)return;timeout=setTimeout(()=>controller.abort(),105000);file.message='Claude is reading your transcript. This can take up to 90 seconds…';renderFiles();const response=await fetch('/api/portal/transcript-import',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Portal-Request':'1',Accept:'text/event-stream'},signal:controller.signal,body:JSON.stringify({consent:true,documentKind:file.kind==='degree-audit'?'degree-audit':file.kind==='completed-transcript'?'completed-transcript':'unknown',pages:images.pages})});const result=await streamResult(response,()=>{if(ticket!==epoch)return;file.message='Still reading your transcript. No courses have been added yet…';renderFiles();});if(ticket!==epoch)return;const parsed=Engine.fromRecords(result.rows,{documentKind:result.documentKind,sourceName:file.file.name,extraction:'ai'});if(allRows().filter(row=>row.fileId!==file.id).length+parsed.rows.length>500)throw Error('The result exceeds 500 courses. Use a smaller PDF.');file.parsed=parsed;file.aiResult=result;file.rows=parsed.rows.map((row,index)=>({...row,id:file.id+'-row-'+index,fileId:file.id}));rememberPreview(file);file.aiIssues=result.issues||[];file.message=parsed.rows.length?'AI read '+parsed.rows.length+' proposed course rows. Review them below before adding.':'No individual course rows were found. Use a text-readable transcript or the spreadsheet template.';file.result={...file.result,needsAI:!parsed.rows.length};render();announce('AI reading finished. Check the proposed course rows before adding them.');}catch(error){if(ticket!==epoch)return;file.message=error.name==='AbortError'?'AI reading stopped before it finished. Your saved courses are unchanged.':error.message;showError(file.message);renderFiles();}finally{clearTimeout(timeout);if(file.controller===controller)file.controller=null;if(ticket===epoch){setBusy(false);renderFiles();selection();}}}
 function findRow(id){return rows.find(row=>row.id===id);}
 $('import-files').addEventListener('change',event=>chooseFiles(event.target.files));$('import-add-files').addEventListener('click',()=>$('import-files').click());
 const drop=$('import-dropzone');for(const name of['dragenter','dragover'])drop.addEventListener(name,event=>{event.preventDefault();if(!busy)drop.classList.add('is-dragging');});for(const name of['dragleave','drop'])drop.addEventListener(name,event=>{event.preventDefault();drop.classList.remove('is-dragging');});drop.addEventListener('drop',event=>chooseFiles(event.dataTransfer.files));
 $('import-cancel').addEventListener('click',()=>{epoch++;for(const file of files){file.controller?.abort();file.reader.cancel();if(/reading|preparing|opening|Claude/i.test(file.message||''))file.message='Reading cancelled. Your saved courses are unchanged.';}setBusy(false);renderFiles();selection();announce('Reading cancelled. Nothing was added.');});
 $('import-rows').addEventListener('change',event=>{const target=event.target;clearError();if(target.dataset.select){const row=findRow(target.dataset.select);if(row)row.selected=target.checked;selection();return;}const row=findRow(target.dataset.row),name=target.dataset.field;if(!row||!['provider','code','title','credits','creditSystem','status','grade','score','completedOn'].includes(name))return;row.issues=row.issues.filter(issue=>issue.origin!=='parser'||issue.field!==name);row.record[name]=['credits','score'].includes(name)?target.value===''?null:Number(target.value):['creditSystem','status'].includes(name)?target.value||null:target.value;try{refresh();renderRows();}catch(error){showError(error);}});
 $('import-attention-only').addEventListener('change',renderRows);
 $('import-select-valid').addEventListener('click',()=>{try{refresh();for(const row of rows)row.selected=!attention(row);renderRows();announce('Ready courses selected. Rows needing attention stay unchecked.');}catch(error){showError(error);}});
 $('import-skip-conflicts').addEventListener('click',()=>{for(const row of rows)if(row.match?.kind==='conflict')row.selected=false;renderRows();announce('Your saved versions will be kept. You can add the other selected courses.');});
 $('import-fill-missing').addEventListener('click',()=>{const provider=$('batch-provider').value.trim(),units=$('batch-units').value,progress=$('batch-status').value;for(const row of rows){if(!row.record.provider&&provider){row.record.provider=provider;row.issues=row.issues.filter(issue=>issue.origin!=='parser'||issue.field!=='provider');}if(!row.source?.isTransfer&&row.documentKind!=='degree-audit'){if(!row.record.creditSystem&&units){row.record.creditSystem=units;row.issues=row.issues.filter(issue=>issue.origin!=='parser'||issue.field!=='creditSystem');}if(!row.record.status&&progress){row.record.status=progress;row.issues=row.issues.filter(issue=>issue.origin!=='parser'||issue.field!=='status');}}}try{refresh();for(const row of rows)if(!attention(row))row.selected=true;renderRows();announce('Missing details filled. Review the selected courses before adding.');}catch(error){showError(error);}});
 $('import-file-list').addEventListener('change',async event=>{
  const target=event.target,file=files.find(file=>file.id===(target.dataset.kindFile||target.dataset.sheetFile||target.dataset.aiConsent));if(!file||busy)return;
  if(target.dataset.aiConsent){file.consent=target.checked;renderFiles();return;}
  const previous=target.dataset.kindFile?file.kind||'unknown':String(file.result?.selectedSheet?.index??0);
  if(target.value===previous)return;
  const ticket=epoch;
  if(!confirmReread(file)||ticket!==epoch||busy||!files.includes(file)){target.value=previous;return;}
  if(target.dataset.kindFile){
   let parsed=false;file.kind=target.value;
   try{parseFile(file,file.result);parsed=true;render();}catch(error){if(!parsed){file.kind=previous;target.value=previous;renderFiles();}showError(error);}return;
  }
  if(target.dataset.sheetFile){setBusy(true);try{await read(file,Number(target.value));}finally{if(ticket===epoch){setBusy(false);renderFiles();selection();}}}
 });
 $('import-file-list').addEventListener('click',event=>{const target=event.target.closest('button');if(!target||busy)return;const file=files.find(file=>file.id===(target.dataset.removeFile||target.dataset.readAi));if(!file)return;if(target.dataset.readAi){readAI(file);return;}file.reader.destroy();files=files.filter(item=>item!==file);try{render();}catch(error){showError(error);}});
 $('import-apply').addEventListener('click',()=>{if(busy)return;clearError();try{const result=Workflow.apply(localStorage,rows,baseline);if(!result.ok){if(result.code==='stale-preview'){baseline=result.revision;saved=result.state;refresh();renderRows();}else if(result.prepared){refresh();renderRows();}showError(result.message);return;}saved=result.state;baseline=result.revision;finished=true;$('import-review').hidden=true;$('import-start').hidden=true;$('import-files-panel').hidden=true;$('import-success').hidden=false;$('import-success-message').textContent=result.counts.added+' course'+(result.counts.added===1?'':'s')+' added to My courses.'+(result.counts.duplicates?' '+result.counts.duplicates+' already-saved course'+(result.counts.duplicates===1?' was':'s were')+' kept without duplicates.':'');const hasPlan=Boolean(saved.selectedPathwayId||saved.profile?.pathwayId)&&!saved.sheet?.isExample;$('import-next').href=hasPlan?'plan.html':'compare-plans.html?from=courses';$('import-next').textContent=hasPlan?'See my updated plan →':'Find degrees for my courses →';step('done');announce('Courses saved on this device.');window.dispatchEvent(new CustomEvent('degreepath:save',{detail:{deviceSaved:true}}));$('import-success-title').setAttribute('tabindex','-1');$('import-success-title').focus();for(const file of files)file.reader.destroy();}catch(error){showError(error);}});
 $('import-start-over').addEventListener('click',()=>{files=[];rows=[];finished=false;$('import-success').hidden=true;clearError();try{saved=Workflow.load(localStorage);baseline=Engine.revision(saved.learning);render();}catch(error){showError(error);}});
 window.addEventListener('pagehide',()=>{epoch++;for(const file of files){file.controller?.abort();file.reader.destroy();}});
 $('import-template-help').innerHTML=window.DegreeCreditImport?.helpHTML()||'';
 $('import-app').addEventListener('click',event=>{if(event.target.closest('a[href="#import-column-guide"]'))$('import-column-guide').open=true;});
 try{if(!Engine||!Workflow||!Files)throw Error('The file reader could not load. Reload this page to try again.');saved=Workflow.load(localStorage);baseline=Engine.revision(saved.learning);render();}catch(error){showError(error);$('import-files').disabled=true;}
}());
